import { ZZFX_SAMPLE_RATE, zzfxGenerate, type ZzfxParams } from "./vendor/zzfx";

/** Every interface sound JackOS plays, one per kind of action. */
export const SOUND_NAMES = ["open", "close", "minimize", "maximize", "error", "menu", "startup"] as const;
/** Name of one interface sound; each has a preset in SOUND_PRESETS. */
export type SoundName = (typeof SOUND_NAMES)[number];

/** One synthesised note: ZzFX parameters, started `at` seconds into the sound. */
type Note = { at: number; params: ZzfxParams };

/**
 * Sound designs, generated by ZzFX (MIT) in the browser, so there are no audio files.
 * Params follow ZzFX order: volume, randomness, frequency, attack, sustain, release, shape, curve, slide.
 */
export const SOUND_PRESETS: Record<SoundName, Note[]> = {
  // Short rising triangle blip.
  open: [{ at: 0, params: [0.8, 0, 520, 0.01, 0.02, 0.08, 1, 1.5, 40] }],
  // Mirror of open: falling blip.
  close: [{ at: 0, params: [0.8, 0, 700, 0.01, 0.02, 0.08, 1, 1.5, -40] }],
  // Longer downward swoop, like the window shrinking away.
  minimize: [{ at: 0, params: [0.7, 0, 620, 0, 0.03, 0.14, 1, 1, -70] }],
  // Upward swoop for growing to full screen (and back).
  maximize: [{ at: 0, params: [0.7, 0, 300, 0, 0.03, 0.14, 1, 1, 70] }],
  // Low saw buzz, twice, for File not found.
  error: [
    { at: 0, params: [0.6, 0, 180, 0.005, 0.06, 0.06, 2, 1] },
    { at: 0.14, params: [0.6, 0, 150, 0.005, 0.06, 0.08, 2, 1] },
  ],
  // Soft tick when the JackOS menu opens.
  menu: [{ at: 0, params: [0.5, 0, 900, 0, 0.01, 0.04, 0, 2] }],
  // Four-note rising arpeggio for boot.
  startup: [
    { at: 0, params: [0.7, 0, 523, 0.01, 0.08, 0.12, 1] },
    { at: 0.13, params: [0.7, 0, 659, 0.01, 0.08, 0.12, 1] },
    { at: 0.26, params: [0.7, 0, 784, 0.01, 0.08, 0.12, 1] },
    { at: 0.39, params: [0.8, 0, 1047, 0.01, 0.12, 0.3, 1] },
  ],
};

// Created on first play so visitors who keep sound off never allocate audio.
let audioContext: AudioContext | null = null;
// Each sound is generated once and reused.
const buffers = new Map<SoundName, { at: number; buffer: AudioBuffer }[]>();

/** Builds (once) the audio buffers for a sound's notes. */
function buffersFor(context: AudioContext, name: SoundName) {
  let notes = buffers.get(name);
  if (!notes) {
    notes = SOUND_PRESETS[name].map((note) => {
      // Copy ZzFX's samples into a mono buffer at its sample rate.
      const samples = zzfxGenerate(...note.params);
      const buffer = context.createBuffer(1, samples.length, ZZFX_SAMPLE_RATE);
      buffer.getChannelData(0).set(samples);
      return { at: note.at, buffer };
    });
    buffers.set(name, notes);
  }
  return notes;
}

/** Plays a sound by name. Silent if the browser has no Web Audio or blocks it. */
export function playSound(name: SoundName): void {
  try {
    // Create the context on first use and wake it if autoplay rules started it suspended.
    audioContext ??= new AudioContext();
    if (audioContext.state === "suspended") void audioContext.resume();
    // Schedule every note relative to now so multi-note sounds play in one go.
    const now = audioContext.currentTime;
    for (const note of buffersFor(audioContext, name)) {
      const source = audioContext.createBufferSource();
      source.buffer = note.buffer;
      source.connect(audioContext.destination);
      source.start(now + note.at);
    }
  } catch {
    // No audio support: stay silent.
  }
}
